async function action(button,fn){button.disabled=true;try{await fn();await refreshData();toast('Operação confirmada na nuvem.')}catch(e){toast(errorText(e)+' Atualize os dados antes de repetir.')}finally{button.disabled=false}}
function bind(){if(page==='reports')bindReports();if($('#anniversary-month'))$('#anniversary-month').onchange=e=>{if(!/^\d{4}-\d{2}$/.test(e.target.value))return;dashboardMonth=e.target.value;render();};document.querySelectorAll('[data-sale-details]').forEach(b=>b.onclick=()=>saleDetails(b.dataset.saleDetails));const search=$('#search');if(search)search.oninput=e=>{const pos=e.target.selectionStart;query=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)};for(const id of ['from','to','status'])if($('#'+id))$('#'+id).onchange=e=>{if(id==='from')from=e.target.value;if(id==='to')to=e.target.value;if(id==='status')statusFilter=e.target.value;render()};document.querySelectorAll('[data-new]').forEach(b=>b.onclick=()=>openForm(b.dataset.new));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openForm(page,b.dataset.edit));document.querySelectorAll('[data-delete]').forEach(b=>{if(page==='products')b.textContent='Desativar';b.onclick=()=>{if(confirm(page==='products'?'Desativar este produto para novas vendas?':'Excluir este registro?'))action(b,()=>cloud.remove(page,b.dataset.delete))}});document.querySelectorAll('[data-paid]').forEach(b=>b.onclick=()=>{if(confirm('Confirmar o recebimento desta venda?'))action(b,()=>cloud.receive(b.dataset.paid))});if($('#export'))$('#export').onclick=exportCSV;if($('#print'))$('#print').onclick=()=>window.print();if($('#refresh-data'))$('#refresh-data').onclick=e=>action(e.target,()=>Promise.resolve());if($('#legacy-export'))$('#legacy-export').onclick=()=>{const data={};for(let i=0;i<localStorage.length;i++){let key=localStorage.key(i);if(key==='siciliano-v1'||key==='siciliano-v1:'+cloud.user)data[key]=JSON.parse(localStorage.getItem(key));}if(!Object.keys(data).length)return toast('Nenhum dado antigo neste navegador e endereço.');download(JSON.stringify(data,null,2),'application/json','siciliano-dados-locais.json');};}
