function openForm(kind,id){if(kind==='sales')return openSaleForm();if(kind==='users')return userForm(id);if(kind==='sales'&&(!db.clients.length||!db.products.some(p=>p.active!==false)))return toast('Cadastre um cliente e um produto antes da venda.');if(!allowedPage(kind))return toast('Seu perfil não permite esta operação.');const requestId=crypto.randomUUID();const available=db.products.filter(p=>p.active!==false);const x=db[kind].find(x=>x.id===id)||{};$('#error').textContent='';$('#modal-title').textContent=(id?'Editar ':'Novo ')+({clients:'cliente',products:'produto',sales:'registro de venda',entries:'lançamento'}[kind]);let h='';if(kind==='clients')h=input('name','Nome completo','text',x.name,'required maxlength="100"')+input('phone','Telefone','tel',x.phone,'required maxlength="25"')+input('email','E-mail','email',x.email,'maxlength="120"');if(kind==='products')h=input('name','Nome do produto','text',x.name,'required maxlength="120"')+input('material','Material / variante','text',x.material,'maxlength="200"')+select('category','Categoria',['Armação','Lente','Solar','Acessório','Não informado'].map(v=>[v,v]),x.category)+input('price','Preço de venda (R$)','number',x.price,'min="0.01" step="0.01"')+'<p class="note">Deixe o preço vazio enquanto não for definido. Produtos iniciam com estoque zero. Após salvar, use Estoque para registrar a entrada.</p>';if(kind==='entries')h=input('description','Descrição','text',x.description,'required maxlength="140"')+select('type','Tipo',[['Entrada','Entrada'],['Saída','Saída']],x.type)+input('value','Valor (R$)','number',x.value,'required min="0.01" step="0.01"')+input('date','Data','date',x.date||day(),'required');if(kind==='sales')h=select('client','Cliente',db.clients.map(x=>[x.id,x.name]),'')+select('product','Produto',available.map(x=>[x.id,x.name]),'')+input('quantity','Quantidade','number',1,'required min="1" step="1"')+input('value','Valor total (R$)','number',available[0].price,'required min="0.01" step="0.01"')+input('date','Data da venda','date',day(),'required')+select('payment','Forma de pagamento',['Pix','Cartão','Dinheiro','Boleto'].map(v=>[v,v]),'Pix')+select('status','Situação',[['Pago','Pago'],['Pendente','Pendente']],'Pago');$('#fields').innerHTML=h;if(kind==='sales'){const recalc=()=>{$('#form [name=value]').value=(db.products.find(p=>p.id===$('#form [name=product]').value).price*Number($('#form [name=quantity]').value)).toFixed(2)};$('#form [name=product]').onchange=recalc;$('#form [name=quantity]').oninput=recalc}let committed=false;$('#form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;$('#error').textContent='';try{if(!committed){let data=Object.fromEntries(new FormData(e.target));for(const key of ['price','quantity','value'])if(key in data)data[key]=key==='price'&&data[key]===''?null:Number(data[key]);for(const key of ['name','description'])if(key in data){data[key]=data[key].trim();if(!data[key])throw Error('Preencha o nome ou a descrição.');}if(kind==='clients'||kind==='products'){data.name=data.name.toLocaleUpperCase('pt-BR');if(kind==='products')data.material=(data.material||'').trim().toLocaleUpperCase('pt-BR');}await cloud.save(kind,data,id,requestId);committed=true;}await refreshData();$('dialog').close();toast('Registro salvo na nuvem.');}catch(error){$('#error').textContent=committed?'Registro salvo, mas a atualização falhou. Tente novamente para recarregar.':errorText(error);}finally{button.disabled=false}};$('dialog').showModal()}
function download(data,type,file){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=file;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}function exportCSV(){let rows;if(['reports','sales'].includes(page))rows=[['Cliente','Produto','Quantidade','Data','Valor total','Situação','Pagamento',...SaleFields.keys.map(k=>SaleFields.labels[k]),'DATA_INCLUSAO'],...filteredSales().map(x=>[name(x.client),x.productLabel||product(x.product),x.quantity,x.date,x.value,x.status,x.payment,...SaleFields.keys.map(k=>x[k]??''),x.created_at||''])];else{let cols=page==='clients'?['name','phone','email']:page==='products'?['name','material','category','price','stock']:['description','type','date','value'];let titles=page==='clients'?['Nome','Telefone','E-mail']:page==='products'?['Produto','Material','Categoria','Preço','Estoque']:['Descrição','Tipo','Data','Valor'];rows=[titles,...db[page].filter(x=>JSON.stringify(x).toLowerCase().includes(query.toLowerCase())&&(!from||!x.date||x.date>=from)&&(!to||!x.date||x.date<=to)).map(x=>cols.map(k=>x[k]))]}download('\ufeff'+rows.map(r=>r.map(v=>'"'+String(/^[=+@\-]/.test(String(v))?"'"+v:v).replaceAll('"','""')+'"').join(';')).join('\r\n'),'text/csv;charset=utf-8',`siciliano-${page}-${day()}.csv`);toast('Relatório exportado.')}
$('#new').onclick=()=>openForm(['inicio','sales'].includes(page)?'sales':page);$('#close').onclick=$('#cancel').onclick=()=>$('dialog').close();$('#backup').onclick=()=>download(JSON.stringify({format:'siciliano-cloud-export-v1',store:cloud.store,exportedAt:new Date().toISOString(),data:db},null,2),'application/json',`siciliano-backup-${day()}.json`);function route(reset=true){page=location.hash.slice(1);if(!pages[page]||!allowedPage(page))page=fullAccess()?'inicio':'clients';if(reset){query='';from='';to='';statusFilter='';}render()}window.onhashchange=()=>route();
document.querySelector('#reload-data').onclick=e=>action(e.target,()=>Promise.resolve());

function openSaleForm(){
 if(!allowedPage('sales'))return toast('Seu perfil não permite esta operação.');
 const available=db.products.filter(p=>p.active!==false);if(!available.length)return toast('Cadastre um produto ativo antes da venda.');
 const dialog=$('dialog');dialog.classList.add('sale-dialog');$('#error').textContent='';$('#modal-title').textContent='Nova venda e receita';
 $('#fields').innerHTML=`<fieldset class="sale-section sale-row"><legend>Atendimento</legend><label class="sale-wide">Buscar cliente<input id="sale-client-search" type="search" placeholder="Digite o nome ou telefone"></label>${select('client','Cliente',[['','Selecione um cliente']], '')}${select('product','Produto',available.map(p=>[p.id,[p.name,p.material].filter(Boolean).join(' — ')]),available[0].id)}${input('quantity','Quantidade','number',1,'required min="1" step="1"')}${input('date','Data da venda','date',day(),'required')}${select('payment','Pagamento',['Pix','Cartão','Dinheiro','Boleto'].map(v=>[v,v]),'Pix')}${select('status','Situação',[['Pago','Pago'],['Pendente','Pendente']],'Pago')}</fieldset>`+SaleFields.html(input,select,{categoria:available[0].category},day());
 const form=$('#form');const field=k=>form.elements.namedItem(k);field('client').required=true;
 const clientSearch=$('#sale-client-search').closest('label');
 clientSearch.insertAdjacentHTML('afterend',`<label class="sale-wide sale-check"><input id="sale-new-client" type="checkbox">Cliente não cadastrado — cadastrar agora</label><fieldset id="sale-client-create" class="sale-section sale-row sale-wide" hidden><legend>Novo cliente</legend>${input('new_client_name','Nome completo do novo cliente','text','','maxlength="100"')}${input('new_client_phone','Telefone do novo cliente','tel','','maxlength="25"')}${input('new_client_email','E-mail do novo cliente','email','','maxlength="120"')}<div class="sale-wide"><button type="button" id="sale-save-client" class="primary">Salvar cliente e selecionar</button><p class="note">Nome e telefone obrigatórios. O cliente será cadastrado mesmo se a venda for cancelada.</p><p id="sale-client-error" role="status"></p></div></fieldset>`);
 $('#sale-client-create').hidden=true;
 const toggleClient=()=>{const enabled=$('#sale-new-client').checked;$('#sale-client-create').hidden=!enabled;for(const key of ['new_client_name','new_client_phone','new_client_email'])field(key).disabled=!enabled;field('client').disabled=enabled;$('#sale-client-search').disabled=enabled;};$('#sale-new-client').onchange=toggleClient;toggleClient();
 $('#sale-save-client').onclick=async()=>{const button=$('#sale-save-client');$('#sale-client-error').textContent='';const data={name:field('new_client_name').value.trim().toLocaleUpperCase('pt-BR'),phone:field('new_client_phone').value.trim(),email:field('new_client_email').value.trim()};if(!data.name||!data.phone)return $('#sale-client-error').textContent='Preencha o nome completo e o telefone.';if(!field('new_client_email').checkValidity())return field('new_client_email').reportValidity();const digits=data.phone.replace(/\D/g,'');if(!/^(?:55)?\d{10,11}$/.test(digits)||/^0+$/.test(digits))return $('#sale-client-error').textContent='Informe um telefone válido com DDD.';button.disabled=true;$('#sale-new-client').disabled=true;try{const id=await cloud.save('clients',data);db.clients.push({...data,id});$('#sale-client-search').value='';listClients();field('client').insertAdjacentHTML('beforeend',field('client').querySelector(`option[value="${CSS.escape(id)}"]`)?'':`<option value="${esc(id)}">${esc(data.name)} — ${esc(data.phone)}</option>`);field('client').value=id;$('#sale-new-client').checked=false;toggleClient();for(const key of ['new_client_name','new_client_phone','new_client_email'])field(key).value='';toast('Cliente cadastrado e selecionado.');}catch(error){$('#sale-client-error').textContent=errorText(error);}finally{button.disabled=false;$('#sale-new-client').disabled=false;}};
 field('product').closest('label').insertAdjacentHTML('beforebegin','<label class="sale-wide">Buscar produto<input id="sale-product-search" type="search" placeholder="Digite nome, material ou categoria"><span id="sale-product-result" role="status"></span></label>');
 const listClients=()=>{const term=$('#sale-client-search').value.toLocaleLowerCase('pt-BR');const matches=db.clients.filter(c=>(c.name+' '+c.phone).toLocaleLowerCase('pt-BR').includes(term)).slice(0,100);field('client').innerHTML='<option value="">Selecione um cliente (até 100 resultados)</option>'+matches.map(c=>`<option value="${esc(c.id)}">${esc(c.name)} — ${esc(c.phone)}</option>`).join('');};$('#sale-client-search').oninput=listClients;listClients();
 const total=()=>{const armacao=field('valor_armacao').value,lente=field('valor_lente').value;field('value').value=armacao===''&&lente===''?'':((Math.round(Number(armacao||0)*100)+Math.round(Number(lente||0)*100))/100).toFixed(2);};
 const recalc=(reset=true)=>{const p=available.find(p=>p.id===field('product').value);if(!p){field('valor_armacao').value='';field('valor_lente').value='';field('categoria').value='';total();return;}if(p.price==null){if(reset){field('valor_armacao').value='';field('valor_lente').value='';}}else{const value=(p.price*Number(field('quantity').value||0)).toFixed(2);field('valor_armacao').value=p.category==='Lente'?'0.00':value;field('valor_lente').value=p.category==='Lente'?value:'0.00';}field('categoria').value=p.category;total();};
 field('product').required=true;
 const normalize=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR');
 $('#sale-product-search').oninput=()=>{const selected=field('product').value,term=normalize($('#sale-product-search').value.trim());const matches=available.filter(p=>normalize([p.name,p.material,p.category].join(' ')).includes(term));field('product').innerHTML=matches.length?matches.map(p=>`<option value="${esc(p.id)}">${esc([p.name,p.material].filter(Boolean).join(' — '))}</option>`).join(''):'<option value="">Nenhum produto encontrado</option>';if(matches.some(p=>p.id===selected))field('product').value=selected;$('#sale-product-result').textContent=matches.length?`${matches.length} produto(s) encontrado(s)`:'Nenhum produto encontrado. Ajuste a pesquisa.';if(field('product').value!==selected)recalc(true);};
 field('product').onchange=()=>recalc(true);field('quantity').oninput=()=>recalc(false);field('valor_armacao').oninput=total;field('valor_lente').oninput=total;recalc();
 const requestId=crypto.randomUUID();let committed=false;let payload;
 form.onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;$('#error').textContent='';try{if($('#sale-new-client').checked)throw Error('Salve o novo cliente antes de registrar a venda.');if(!committed){payload||=SaleFields.read(form);await cloud.save('sales',payload,null,requestId);committed=true;}await refreshData();dialog.close();toast('Venda e receita salvas na nuvem.');}catch(error){if(error.code&&error.code!=='PGRST301')payload=null;$('#error').textContent=committed?'Venda salva. Tente novamente para atualizar a lista.':error.code==='PGRST202'?'A atualização dos campos de venda ainda não está disponível no banco.':errorText(error);}finally{button.disabled=false;}};
 dialog.showModal();
}
function saleDetails(id){const sale=db.sales.find(s=>s.id===id);if(!sale)return;const dialog=$('dialog');dialog.classList.add('sale-dialog');$('#modal-title').textContent='Detalhes da venda';$('#error').textContent='';$('#fields').innerHTML=`<div class="sale-section"><h2>${esc(name(sale.client))}</h2><p>${esc(sale.productLabel||product(sale.product))} · ${fmt(sale.date)} · ${money(sale.value)}</p><p>${esc(sale.status)} · ${esc(sale.payment)}</p></div>`+SaleFields.html(input,select,{...sale,data_input:sale.data_input??'',valor_armacao:sale.valor_armacao??'',valor_lente:sale.valor_lente??''},'');$('#fields').querySelectorAll('input,select,textarea').forEach(e=>e.disabled=true);$('#form .primary').hidden=true;$('#cancel').textContent='Fechar';$('#form').onsubmit=e=>e.preventDefault();dialog.showModal();}
$('dialog').addEventListener('close',()=>{$('dialog').classList.remove('sale-dialog');$('#form .primary').hidden=false;$('#cancel').textContent='Cancelar';});
